class LoggingProxy : DispatchProxy {
    private IService? _target;
    public static IService Create(IService target) {
        var p = Create<IService, LoggingProxy>();
        ((LoggingProxy)p)._target = target;
        return p;
    }
    protected override object? Invoke(MethodInfo m, object?[]? args) {
        Console.WriteLine(m.Name);
        return m.Invoke(_target, args);          // wraps failures in TargetInvocationException
    }
}

