var generator = new ProxyGenerator();                    // reuse: it caches generated types
var service = generator.CreateInterfaceProxyWithTarget<IService>(
    target, new LoggingInterceptor());

class LoggingInterceptor : IInterceptor {
    public void Intercept(IInvocation invocation) {
        Console.WriteLine(invocation.Method.Name);
        invocation.Proceed();
    }
}

[Generator]
public partial class ProxyGenerator : IIncrementalGenerator {
    public void Initialize(IncrementalGeneratorInitializationContext ctx) {
        var interfaces = ctx.SyntaxProvider.ForAttributeWithMetadataName(
            "App.ProxyForAttribute", predicate: static (_, _) => true, transform: static (c, _) => c);
        ctx.RegisterSourceOutput(interfaces, EmitForwarder);   // emits class IServiceProxy : IService
    }
}
